    /// <summary>The tagged-sum CBOR value for a CheckValue: [variant_index, value].</summary>
    public static CborValue CheckValueToCborValue(CheckValue value) => value switch
    {
        CheckValueVariant1 csilArm => new CborValue.Array(new CborValue[] { new CborValue.Uint(0), (CborValue)new CborValue.Text(csilArm.Value) }),
        CheckValueVariant2 csilArm => new CborValue.Array(new CborValue[] { new CborValue.Uint(1), (CborValue)new CborValue.Int(csilArm.Value) }),
        CheckValueVariant3 csilArm => new CborValue.Array(new CborValue[] { new CborValue.Uint(2), (CborValue)new CborValue.Float(csilArm.Value) }),
        _ => throw new CborException("invalid CheckValue"),
    };

